export default "/* src/client/styles/memory.module.css */\n.memory_panel {\n  display: grid;\n  gap: 16px;\n  padding: 22px 24px;\n  color: var(--dsw-alias-label-primary);\n  min-width: 0;\n  max-width: 100%;\n  box-sizing: border-box;\n}\n.memory_panel :where(section, aside, form, fieldset, [role=tablist]) {\n  min-width: 0;\n  max-width: 100%;\n  box-sizing: border-box;\n}\n.memory_panel :where(p, legend, label, button) {\n  overflow-wrap: anywhere;\n}\n.memory_panel [role=tablist],\n.memory_panel [data-shared-memory-panel] :where(div, form) {\n  flex-wrap: wrap;\n  white-space: normal;\n}\n.memory_panel button {\n  max-width: 100%;\n  white-space: normal;\n}\n.memory_panel [data-qualifier-row] {\n  display: flex;\n  align-items: end;\n  gap: 8px;\n  margin-bottom: 12px;\n}\n.memory_panel p,\n.memory_panel h3 {\n  margin: 0;\n}\n.memory_panel .memory_search {\n  --memory-search-gap: 8px;\n  display: flex;\n  align-items: flex-end;\n  gap: var(--memory-search-gap);\n  flex-wrap: wrap;\n  padding: 0;\n  border: 0;\n  background: var(--dsw-alias-bg-base);\n  min-width: 0;\n}\n.memory_searchGroup {\n  display: flex;\n  align-items: flex-end;\n  flex-wrap: wrap;\n  gap: var(--memory-search-gap);\n  min-width: 0;\n  max-width: 100%;\n}\n.memory_searchGroup > label {\n  flex: 1 1 12rem;\n  min-width: min(100%, 12rem);\n}\n.memory_panel [data-qualifier-row] label {\n  flex: 1 1 120px;\n  min-width: 0;\n}\n.memory_panel .memory_search button {\n  align-self: flex-end;\n}\n.memory_refresh {\n  margin-inline-start: auto;\n}\n.memory_form {\n  display: grid;\n  gap: 16px;\n  border: 1px solid var(--dsw-alias-border-l3);\n  border-radius: 12px;\n  padding: 16px;\n}\n.memory_form h3 {\n  font-size: 16px;\n}\n.memory_list {\n  list-style: none;\n  display: grid;\n  gap: 12px;\n  padding: 0;\n  margin: 0;\n}\n.memory_record {\n  display: grid;\n  gap: 12px;\n  min-width: 0;\n  padding: 16px;\n  border: 1px solid var(--dsw-alias-border-l3);\n  border-radius: 12px;\n  background: v