export default "/* src/client/styles/capabilities.module.css */\n.capabilities_panel {\n  min-width: 0;\n  margin: 16px 0;\n  color: var(--dsw-alias-label-primary);\n  font-size: 13px;\n  line-height: 1.5;\n}\n.capabilities_panel h3 {\n  font-size: 16px;\n  margin: 0;\n}\n.capabilities_panel p {\n  color: var(--dsw-alias-label-secondary);\n}\n.capabilities_panel ul {\n  display: grid;\n  padding: 0;\n  gap: 10px;\n  list-style: none;\n}\n.capabilities_panel li {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  padding: 12px;\n  background: var(--dsw-alias-bg-base);\n}\n.capabilities_panel li span {\n  flex: 1 1 160px;\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n.capabilities_panel button {\n  margin: 3px;\n  min-height: 36px;\n}\n.capabilities_panel textarea:focus-visible {\n  outline: 2px solid var(--dsw-alias-label-primary);\n  outline-offset: 2px;\n}\n.capabilities_panel form {\n  display: grid;\n  gap: 10px;\n}\n.capabilities_panel textarea {\n  box-sizing: border-box;\n  display: block;\n  width: 100%;\n  min-height: 80px;\n  resize: vertical;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-base);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  padding: 8px;\n}\n@media (max-width: 480px) {\n  .capabilities_panel li {\n    padding: 8px;\n  }\n  .capabilities_panel li span {\n    flex-basis: 100%;\n  }\n}\n.capabilities_panel input:not([type=checkbox]) {\n  box-sizing: border-box;\n  display: block;\n  width: 100%;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-base);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  padding: 8px;\n}\n";