export default "/* src/client/styles/avatar.module.css */\n.avatar_picker {\n  min-width: 0;\n  padding: 16px;\n  border: 1px solid var(--dsw-alias-border-l3);\n  border-radius: 12px;\n}\n.avatar_previewRow {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  flex-wrap: wrap;\n}\n.avatar_palette {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 12px;\n  margin-top: 12px;\n}\n.avatar_swatches,\n.avatar_emojis {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n.avatar_swatches {\n  width: 100%;\n  box-sizing: border-box;\n  border: 0;\n  padding: 0;\n  margin: 0;\n  min-width: 0;\n}\n.avatar_swatches legend {\n  margin-bottom: 6px;\n}\n.avatar_swatch {\n  display: inline-flex;\n  padding: 2px;\n  border-radius: 10px;\n  border: 2px solid var(--dsw-alias-border-l3);\n  background: var(--dsw-alias-bg-base);\n  cursor: pointer;\n}\n.avatar_swatch[aria-pressed=true] {\n  border-color: var(--dsw-alias-state-business-primary);\n}\n.avatar_swatch:focus-visible {\n  outline: 2px solid var(--dsw-alias-state-business-primary);\n  outline-offset: 2px;\n}\n.avatar_swatch:disabled {\n  cursor: default;\n  opacity: 0.6;\n}\n.avatar_other {\n  margin-top: 16px;\n}\n.avatar_other summary {\n  cursor: pointer;\n  color: var(--dsw-alias-label-secondary);\n}\n.avatar_emojis {\n  margin: 12px 0;\n}\n";